import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS, en, T, idx, DUR, Camara, Textura, Profundidad, Brillo, Paso, tono, Regla, Chip, Ondas, Destello, sacudida, golpe,  Easing, interpolate, clamp, h, FONT} from './kit';

// ---------- utilidades ----------
const cl = (v: number, a = 0, b = 1) => Math.max(a, Math.min(b, v));
const eo = (x: number) => 1 - Math.pow(1 - cl(x), 3);
const eio = (x: number) => { const k = cl(x); return k < 0.5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2; };
const ro = (s: number, a: number, b: number) => cl((s - a) / (b - a));
const P = (t: number, x: number, y: number, z: number) => ({t, x: cl(x, 540 / z, 1080 - 540 / z), y: cl(y, 1000 / z, 1920 - 920 / z), zoom: z});
const scr = (c: {x: number; y: number; zoom: number}, x: number, y: number) => ({x: 540 + (x - c.x) * c.zoom, y: 1000 + (y - c.y) * c.zoom});
const GOLD = '#FFC83D';
const RED = '#FF4D4D';
const GREEN = '#2FBF71';
const fix = (l: {t: number; s: string}[]) => {
  const o: {t: number; s: string}[] = [];
  let last = -9;
  [...l].sort((a, b) => a.t - b.t).forEach((e) => { if (e.t - last >= 0.27) { o.push(e); last = e.t; } });
  return o;
};
const fmt = (v: number) => Math.round(v).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
const pulso = (s: number, t: number) => Math.max(0, golpe(s, t, 22, 8));
const burstPts = (r1: number, r2: number, n: number) => Array.from({length: n * 2}).map((_, i) => { const r = i % 2 ? r2 : r1; const a = (i / (n * 2)) * Math.PI * 2; return `${(Math.cos(a) * r).toFixed(1)},${(Math.sin(a) * r).toFixed(1)}`; }).join(' ');
const starPts = (r: number) => `0,${-r} ${r * 0.28},${-r * 0.28} ${r},0 ${r * 0.28},${r * 0.28} 0,${r} ${-r * 0.28},${r * 0.28} ${-r},0 ${-r * 0.28},${-r * 0.28}`;

// ---------- tiempos (todo atado a palabras del guion) ----------
// E1
const PAGASTE = en('pagaste'), LLEGO1 = en('llegó', 1), NADA = en('nada');
// E2
const UNOS = en('unos'), TENIS = en('tenis'), MARCA = en('marca'), MITAD = en('mitad'), PRECIO1 = en('precio', 1), ANUNCIO2 = en('anuncio', 2), BONITO = en('bonito');
const REDW = en('red', 1), SOCIAL = en('social'), PAGINA1 = en('página', 1), PARECE = en('parece'), VERDAD = en('verdad');
// E3
const PAGAS = en('pagas'), LLEGA = en('llega'), CORREO = en('correo'), CONFIRM = en('confirmación'), ESPERAS = en('esperas'), SEMANA = en('semana'), MES = en('mes'), PAGINA2 = en('página', 2), EXISTE = en('existe');
// E4
const EN = T(idx('estados') - 1), UNIDOS = en('unidos'), FTC = en('ftc'), DOS1 = en('dos', 1), GENTE = en('gente'), PERDIO = en('perdió'), DOS2 = en('dos', 2), MILLONES = en('millones'), DOLARES = en('dólares');
const ESTAFAS = en('estafas'), EMPEZARON = en('empezaron'), REDES = en('redes'), SOCIALES = en('sociales'), OCHO = en('ocho'), VECES = en('veces'), MAS = en('más', 1), DOS3 = en('dos', 3), VEINTE = en('veinte');
// E5
const Y5 = T(idx('estafa', 1) - 1), ESTAFA1 = en('estafa', 1), REPORTADA = en('reportada'), COMPRAS = en('compras'), NUNCA2 = en('nunca', 2), LLEGARON = en('llegaron');
const CUARENTA = en('cuarenta'), CIENTO = en('ciento'), VIO = en('vio'), ANUNCIO3 = en('anuncio', 3);
// E6
const EL = T(idx('truco') - 1), TRUCO = en('truco'), PRECIO2 = en('precio', 2), BUENO = en('bueno'), DEJARLO = en('dejarlo'), PRISA = en('prisa'), HACE = en('hace'), PAGAR = en('pagar');
// E7
const ANTES = en('antes'), COMPRAR = en('comprar'), BUSCA = en('busca'), NOMBRE = en('nombre'), TIENDA = en('tienda'), PALABRA = en('palabra'), ESTAFA2 = en('estafa', 2);
const SI = en('si', 1), ACEPTAN = en('aceptan'), TRANSF = en('transferencia'), PAGO = en('pago'), RARO = en('raro'), SAL = en('sal'), AHI = en('ahí');
// E8
const DALE = en('dale'), LIKE = en('like'), COMENTA = en('comenta'), NUNCA3 = en('nunca', 3), ENVIASELO = en('envíaselo'), ANUNCIOS = en('anuncios');

// ---------- piezas dibujadas ----------
const Zapatilla: React.FC<{c1?: string; c2?: string}> = ({c1 = '#ff3d81', c2 = '#ffd84d'}) => (
  <g>
    <ellipse cx={10} cy={90} rx={190} ry={14} fill="rgba(0,0,0,0.28)" />
    <path d="M -165 70 Q -172 36 -142 34 L 178 34 Q 200 36 196 58 Q 192 82 162 82 L -128 82 Q -158 82 -165 70 Z" fill="#fff" stroke="#c4cad6" strokeWidth={4} />
    <path d="M -140 34 L -128 -34 Q -118 -66 -80 -66 L -36 -66 Q -4 -14 52 -6 L 148 12 Q 192 22 190 34 Z" fill={c1} stroke="#9c2150" strokeWidth={4} strokeLinejoin="round" />
    <path d="M -60 -66 L -44 -112 L -2 -108 L 10 -52 Z" fill="#ff7aa8" stroke="#9c2150" strokeWidth={4} strokeLinejoin="round" />
    <path d="M -118 16 Q -20 -22 108 8" stroke={c2} strokeWidth={14} fill="none" strokeLinecap="round" />
    <path d="M 96 8 Q 150 12 188 30 L 120 34 Z" fill="rgba(255,255,255,0.28)" />
    <path d="M -134 28 L -124 -28" stroke="rgba(255,255,255,0.45)" strokeWidth={8} strokeLinecap="round" />
    {[0, 1, 2, 3].map((i) => <line key={i} x1={-34 + i * 24} y1={-44 + i * 13} x2={-6 + i * 24} y2={-62 + i * 13} stroke="#fff" strokeWidth={7} strokeLinecap="round" />)}
  </g>
);

const HeroAd: React.FC<{w: number; alto: number; sc?: number; shoe?: number}> = ({w, alto, sc = 1, shoe = 1}) => {
  const {s} = useS();
  const R = Math.max(w, alto);
  const id = 'hc' + Math.round(w);
  return (
    <g>
      <defs>
        <linearGradient id="adGrad" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stopColor="#ff4fa3" /><stop offset="100%" stopColor="#ff9a3d" /></linearGradient>
        <clipPath id={id}><rect x={-w / 2} y={-alto / 2} width={w} height={alto} rx={28} /></clipPath>
      </defs>
      <g clipPath={`url(#${id})`}>
        <rect x={-w / 2} y={-alto / 2} width={w} height={alto} fill="url(#adGrad)" />
        {Array.from({length: 14}).map((_, i) => {
          const a0 = (i / 14) * Math.PI * 2 + s * 0.18;
          const a1 = a0 + 0.15;
          return <polygon key={i} points={`0,0 ${Math.cos(a0) * R},${Math.sin(a0) * R} ${Math.cos(a1) * R},${Math.sin(a1) * R}`} fill="rgba(255,255,255,0.15)" />;
        })}
        <ellipse cx={0} cy={alto * 0.22} rx={w * 0.36} ry={alto * 0.07} fill="rgba(90,20,50,0.35)" />
        <g transform={`translate(0 ${-alto * 0.02 + Math.sin(s * 2.4) * 8}) scale(${sc * shoe}) rotate(${-8 + Math.sin(s * 1.6) * 3})`}>
          <Zapatilla />
        </g>
      </g>
    </g>
  );
};

const Celular: React.FC<{x: number; y: number; k?: number; pantalla?: string; children?: React.ReactNode}> = ({x, y, k = 1, pantalla = '#0c1a28', children}) => (
  <g transform={`translate(${x} ${y}) scale(${k})`}>
    <rect x={-264} y={-512} width={528} height={1044} rx={78} fill="rgba(0,0,0,0.5)" transform="translate(12 18)" />
    <rect x={-260} y={-520} width={520} height={1040} rx={76} fill="#12151c" stroke="#5a6478" strokeWidth={8} />
    <rect x={-232} y={-492} width={464} height={984} rx={54} fill={pantalla} />
    <clipPath id="celClip"><rect x={-232} y={-492} width={464} height={984} rx={54} /></clipPath>
    <g clipPath="url(#celClip)">{children}</g>
    <rect x={-60} y={-480} width={120} height={22} rx={11} fill="#05070b" />
    <path d="M -232 -492 L -40 -492 L -232 -140 Z" fill="rgba(255,255,255,0.07)" />
  </g>
);

const Mano: React.FC<{x: number; y: number; r?: number; k?: number}> = ({x, y, r = 0, k = 1}) => {
  const F = '#d9a577', L = '#8a5a36';
  return (
    <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
      <rect x={-64} y={80} width={128} height={420} rx={50} fill={F} stroke={L} strokeWidth={4} />
      <rect x={-80} y={-70} width={160} height={190} rx={56} fill={F} stroke={L} strokeWidth={4} />
      {[[-58, 70], [-20, 55], [20, 60], [58, 75]].map(([fx, fl], i) => (
        <rect key={i} x={fx - 17} y={-70 - (i === 1 ? 150 : fl)} width={34} height={(i === 1 ? 150 : fl) + 40} rx={17} fill={F} stroke={L} strokeWidth={3} />
      ))}
      <rect x={-128} y={-20} width={34} height={110} rx={17} fill={F} stroke={L} strokeWidth={3} transform="rotate(-38 -110 60)" />
      <path d="M -80 -20 Q -30 -50 20 -20" stroke="rgba(255,255,255,0.30)" strokeWidth={6} fill="none" strokeLinecap="round" />
      <path d="M 40 0 Q 70 40 56 100" stroke="rgba(0,0,0,0.14)" strokeWidth={10} fill="none" strokeLinecap="round" />
    </g>
  );
};

const Bill: React.FC<{x: number; y: number; r?: number; k?: number; op?: number}> = ({x, y, r = 0, k = 1, op = 1}) => (
  <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`} opacity={op}>
    <rect x={-146} y={-60} width={304} height={144} rx={14} fill="rgba(0,0,0,0.35)" />
    <rect x={-150} y={-70} width={300} height={140} rx={14} fill="#b4d9a2" stroke="#3f6b3a" strokeWidth={5} />
    <rect x={-134} y={-54} width={268} height={108} rx={9} fill="none" stroke="#3f6b3a" strokeWidth={2.5} opacity={0.65} />
    <circle r={42} fill="rgba(255,255,255,0.35)" stroke="#3f6b3a" strokeWidth={3} />
    <text y={15} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={46} fill="#2f5a2b">$</text>
    <path d="M -150 -70 L 24 -70 L -56 70 L -150 70 Z" fill="rgba(255,255,255,0.16)" />
  </g>
