const Cartera: React.FC<{x: number; y: number; k?: number; r?: number; bills?: number; oro?: boolean}> = ({x, y, k = 1, r = 0, bills = 1, oro = false}) => (
  <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
    <defs>
      <linearGradient id="cuero2" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#8a5a34" /><stop offset="60%" stopColor="#5f3a1f" /><stop offset="100%" stopColor="#3d2312" /></linearGradient>
    </defs>
    <ellipse cx={0} cy={140} rx={210} ry={26} fill="rgba(0,0,0,0.4)" />
    {bills > 0.02 && [0, 1, 2].map((i) => <rect key={i} x={-150 + i * 26} y={-120 - 70 * bills * (1 - i * 0.12)} width={250} height={70 * bills + 40} rx={8} fill={['#b4d9a2', '#a3cf92', '#c1e2b2'][i]} stroke="#3f6b3a" strokeWidth={3} transform={`rotate(${(i - 1) * 5})`} />)}
    <rect x={-190} y={-120} width={380} height={250} rx={30} fill="url(#cuero2)" stroke="#2c180a" strokeWidth={5} />
    <rect x={-170} y={-100} width={340} height={210} rx={20} fill="none" stroke={oro ? GOLD : '#c9a074'} strokeWidth={3} strokeDasharray="12 9" opacity={0.85} />
    <path d="M -190 -40 Q 0 -10 190 -40 L 190 -80 Q 0 -110 -190 -80 Z" fill="rgba(255,255,255,0.10)" />
    <rect x={120} y={-24} width={70} height={64} rx={14} fill={oro ? GOLD : '#7a4c28'} stroke="#2c180a" strokeWidth={4} />
    <circle cx={152} cy={8} r={12} fill={oro ? '#fff2b0' : '#c9a074'} />
    {oro && <rect x={-190} y={-120} width={380} height={250} rx={30} fill="none" stroke={GOLD} strokeWidth={6} opacity={0.9} />}
  </g>
);

// caja de envio de carton. abierta 0..1 (solapas), des 0..1 (se desarma), cierre = cinta y etiqueta
const Caja: React.FC<{x: number; y: number; k?: number; r?: number; abierta?: number; des?: number; op?: number}> = ({x, y, k = 1, r = 0, abierta = 0, des = 0, op = 1}) => {
  const a = Math.max(0, Math.min(1.12, abierta));
  const cerrada = a < 0.04;
  return (
    <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`} opacity={op}>
      <defs>
        <linearGradient id="inCaja" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#8a5a2c" /><stop offset="100%" stopColor="#1f1208" /></linearGradient>
      </defs>
      <ellipse cx={30} cy={152} rx={200 + 40 * des} ry={26} fill="rgba(0,0,0,0.42)" />
      {!cerrada && <polygon points={`-50,-100 190,-100 ${200 + 8 * a},${-100 - 74 * a} ${-60 - 8 * a},${-100 - 74 * a}`} fill="#B98249" stroke="#5a3a1a" strokeWidth={4} strokeLinejoin="round" />}
      {!cerrada && <polygon points="-120,-40 120,-40 190,-100 -50,-100" fill="url(#inCaja)" stroke="#3a2410" strokeWidth={4} />}
      <g transform={`translate(120 0) scale(${1 - 0.55 * des} 1) translate(-120 0)`}>
        <polygon points="120,-40 190,-100 190,80 120,140" fill="#A9733C" stroke="#5a3a1a" strokeWidth={4} strokeLinejoin="round" />
        {[0, 1, 2, 3, 4].map((i) => <line key={i} x1={120} y1={-10 + i * 30} x2={190} y2={-70 + i * 30} stroke="rgba(60,36,12,0.28)" strokeWidth={3} />)}
      </g>
      <g transform={`translate(0 140) scale(1 ${1 - 0.5 * des}) translate(0 -140)`}>
        <rect x={-120} y={-40} width={240} height={180} fill="#C98F52" stroke="#5a3a1a" strokeWidth={4} />
        {[0, 1, 2, 3, 4].map((i) => <line key={i} x1={-120} y1={-10 + i * 30} x2={120} y2={-10 + i * 30} stroke="rgba(90,58,26,0.25)" strokeWidth={3} />)}
        <rect x={-120} y={-40} width={240} height={26} fill="rgba(255,255,255,0.10)" />
        {cerrada && <rect x={-10} y={-40} width={40} height={64} fill="#EBDDB5" stroke="#b9a66e" strokeWidth={3} />}
        <g transform="translate(36 60)">
          <rect x={0} y={0} width={80} height={56} rx={4} fill="#fff" stroke="#b9ad8f" strokeWidth={3} />
          {[0, 1, 2].map((i) => <rect key={i} x={8} y={8 + i * 12} width={i === 2 ? 30 : 56} height={6} rx={3} fill="#9aa3b5" />)}
          <rect x={46} y={34} width={26} height={14} fill="#222" />
        </g>
      </g>
      {cerrada ? (
        <g>
          <polygon points="-120,-40 120,-40 190,-100 -50,-100" fill="#DDAA70" stroke="#5a3a1a" strokeWidth={4} strokeLinejoin="round" />
          <polygon points="-10,-40 30,-40 100,-100 60,-100" fill="#EBDDB5" stroke="#b9a66e" strokeWidth={3} />
        </g>
      ) : (
        <g>
          <polygon points={`120,-40 190,-100 ${190 + 52 * a},${-100 + 16 * a} ${120 + 52 * a},${-40 + 16 * a}`} fill="#A9733C" stroke="#5a3a1a" strokeWidth={4} strokeLinejoin="round" />
          <polygon points={`-120,-40 -50,-100 ${-50 - 52 * a},${-100 + 16 * a} ${-120 - 52 * a},${-40 + 16 * a}`} fill="#B98249" stroke="#5a3a1a" strokeWidth={4} strokeLinejoin="round" />
          <polygon points={`-120,-40 120,-40 ${132 + 6 * a},${-40 + 64 * a} ${-132 - 6 * a},${-40 + 64 * a}`} fill="#D9A468" stroke="#5a3a1a" strokeWidth={4} strokeLinejoin="round" />
        </g>
      )}
    </g>
  );
};

const Persona: React.FC<{x: number; y: number; k?: number; c: string; op?: number}> = ({x, y, k = 1, c, op = 1}) => (
