    <path d="M -34 44 L -34 6 Q -34 -14 -14 -14 L 14 -14 Q 34 -14 34 6 L 34 44 Z" fill={c} stroke="rgba(0,0,0,0.35)" strokeWidth={3} />
    <circle cx={0} cy={-40} r={27} fill="#e8b98e" stroke="#8a5a36" strokeWidth={3} />
    <path d="M -26 -44 Q -22 -70 0 -68 Q 24 -70 26 -44 Q 8 -56 -26 -44 Z" fill="#3a2a1f" />
    {[-9, 9].map((ex) => <g key={ex}><circle cx={ex} cy={-38} r={4.2} fill="#2a1640" /><circle cx={ex + 1.4} cy={-39.5} r={1.4} fill="#fff" /></g>)}
