const Alerta: React.FC<{x: number; y: number; k?: number}> = ({x, y, k = 1}) => (
  <g transform={`translate(${x} ${y}) scale(${k})`}>
    <polygon points="0,-34 34,24 -34,24" fill={RED} stroke="#fff" strokeWidth={5} strokeLinejoin="round" />
