const Corazon: React.FC<{x: number; y: number; k?: number; c?: string; op?: number}> = ({x, y, k = 1, c = RED, op = 1}) => (
  <path d="M 0 -18 C -40 -58 -92 -8 0 62 C 92 -8 40 -58 0 -18 Z" fill={c} stroke="#fff" strokeWidth={5} transform={`translate(${x} ${y}) scale(${k})`} opacity={op} />
);

const Polvo: React.FC<{n?: number; color?: string; vel?: number}> = ({n = 24, color = 'rgba(255,240,210,0.5)', vel = 1}) => {
  const {s} = useS();
  return (
    <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>
      {Array.from({length: n}).map((_, i) => {
        const x = h(i * 3 + 1) * 1080 + Math.sin(s * 0.6 + i) * 34;
        const y = (((h(i * 7 + 2) * 1920 - s * (14 + h(i) * 26) * vel) % 1920) + 1920) % 1920;
        return <circle key={i} cx={x} cy={y} r={2 + h(i * 5) * 4} fill={color} opacity={0.25 + h(i * 11) * 0.4} />;
      })}
    </svg>
  );
};

const Cont: React.FC<{t0: number; t1: number; hasta: number; x: number; y: number; esc?: number; op?: number}> = ({t0, t1, hasta, x, y, esc = 1, op = 1}) => {
  const {spr, lin} = useS();
  const pop = spr(t0 - 0.05, 10, 200);
  if (pop <= 0.001 || op <= 0.001) return null;
  const v = lin(t0, t1, 0, hasta, Easing.out(Easing.cubic));
  return (
    <div style={{position: 'absolute', left: x, top: y, opacity: op, transform: `translate(-50%, -50%) scale(${pop * esc})`, background: 'rgba(8,10,20,0.92)', border: `4px solid ${RED}`, borderRadius: 80, padding: '10px 44px', fontFamily: FONT, fontWeight: 800, fontSize: 104, color: RED, whiteSpace: 'nowrap', boxShadow: `0 0 50px ${RED}66`}}>
      ${fmt(v)} M
    </div>
  );
};

// ================= SITIO A: la puerta y el celular (E1 y bucle E8) =================
const PH = {x: 540, y: 780, k: 0.72};
const BTN = {x: PH.x, y: PH.y + 380 * PH.k};
const A_CAM = [P(0, 540, 1000, 1.0), P(2.3, 540, 1060, 1.12)];
const A_END = P(0, 540, 1060, 1.12);
const ENT = scr(A_END, PH.x, PH.y);
const A_CAM_FIN = [P(0, 540, 1000, 1.0), P(DUR, 570, 1070, 1.08)];
const BOX = {x: 540, y: 1500};
const T0F = PAGASTE + 0.15;
const T1F = LLEGO1;
const cajaPos = (s: number) => {
  const p = ro(s, T0F, T1F);
  const e = p * p;
  const rebote = s >= T1F ? Math.abs(golpe(s, T1F, 16, 6)) : 0;
  return {
    x: 540 + Math.sin(p * Math.PI) * 70 * (1 - p),
    y: PH.y + 20 + (BOX.y - PH.y - 20) * e - 30 * rebote,
    k: 0.32 + 0.68 * eo(p),
    r: -28 * (1 - eo(p)) + (s >= T1F ? 5 * golpe(s, T1F, 18, 7) : 0),
  };
};

const SitioA: React.FC<{fase?: 'ini' | 'fin'}> = ({fase = 'ini'}) => {
  const {s, spr} = useS();
  const fn = fase === 'fin';
  const adOp = fn ? ro(s, DUR - 0.65, DUR - 0.15) : 1;
  const flot = Math.sin(s * 1.3) * 7;
  const cp = cajaPos(s);
  const abierta = fn ? 0 : spr(NADA, 9, 150);
  const des = fn ? 0 : eio(ro(s, NADA + 0.3, NADA + 0.55)) * 0.75;
  const offMano = interpolate(s, [0, 0.7, 1.2, 1.35, 1.95], [80, 60, 0, 0, 430], {...clamp, easing: Easing.inOut(Easing.cubic)});
  const tap = pulso(s, PAGASTE + 0.12);
  const boton = 1 - 0.1 * Math.max(0, golpe(s, PAGASTE + 0.12, 20, 9));
  const respira = 1 + 0.018 * Math.sin(s * 2.2);
  const heart = spr(LIKE, 8, 200);
  const burbuja = spr(COMENTA, 8, 200);
  const avion = ro(s, ENVIASELO, ENVIASELO + 1.1);
  return (
    <AbsoluteFill>
      <Camara paradas={fn ? A_CAM_FIN : A_CAM}>
        <Textura tipo="fibra" base="radial-gradient(circle at 50% 62%, #4a3320 0%, #24170d 70%, #120b06 100%)" linea="rgba(201,149,90,0.45)" luz="rgba(255,190,120,0.14)" semilla={2} />
        <AbsoluteFill style={{background: 'linear-gradient(180deg, rgba(8,14,40,0.85) 0%, rgba(8,14,40,0.4) 50%, rgba(0,0,0,0) 72%)'}} />
        <Brillo x={540} y={780} r={560} color={fn ? 'rgba(120,150,255,0.22)' : 'rgba(255,90,160,0.5)'} />
        <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>
