                    <rect x={250} y={r.y - 36} width={Math.max(0.1, r.w * cl(k))} height={26} rx={12} fill="rgba(255,255,255,0.18)" />
                    <circle cx={180} cy={r.y} r={50} fill="#222a3c" stroke={i === 0 ? RED : '#56607a'} strokeWidth={5} />
                    {i === 0 && <Caja x={180} y={r.y - 4} k={0.2} />}
