                    {i === 3 && <g><rect x={162} y={r.y - 28} width={36} height={56} rx={8} fill="#cfd6e4" stroke="#6b7488" strokeWidth={3} /><rect x={168} y={r.y - 20} width={24} height={34} rx={3} fill="#4f8cff" /></g>}
                  </g>
                );
