              {gold1 > 0.05 && (
                <g transform={`translate(${250 + 470 + 50} 790) scale(${spr(REPORTADA, 8, 220)})`}>
                  <circle r={44} fill={GOLD} stroke="#a87a10" strokeWidth={5} />
