              {interr > 0.01 && <text x={540} y={880} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={300 * interr} fill={GOLD} stroke="#7a560a" strokeWidth={6} opacity={cl(interr)}>?</text>}
