              const abre = spr(LLEGARON + 0.02 * i, 9, 170);
              return <Caja key={i} x={q.x + Math.sin(s * 0.5) * 10 * (q.r - 2)} y={y} k={0.55} r={(i % 3 - 1) * 2.5} abierta={s < LLEGARON ? 0 : abre} />;
            })}
          </g>
          {/* anillo del 40 % */}
          {s > CUARENTA - 0.1 && (
            <g opacity={spr(CUARENTA, 12, 140)}>
