              <text x={540} y={820 + 26 + 190 * numMov} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={78 - 18 * numMov} fill="#fff" stroke="rgba(0,0,0,0.6)" strokeWidth={2}>40 %</text>
