};

// ================= SITIO E: el anzuelo y la busqueda (E6 y E7) =================
const E_CAM = [P(EL, 540, 1000, 1.0), P(PRECIO2, 540, 900, 1.15), P(BUENO, 540, 960, 1.1), P(PRISA - 0.1, 540, 1000, 1.1), P(PRISA + 0.7, 600, 1184, 1.22), P(PAGAR, 560, 1100, 1.2), P(ANTES + 0.3, 540, 1000, 1.0), P(BUSCA, 540, 1000, 1.05), P(AHI - 0.8, 540, 1000, 1.12)];
const E_END = P(0, 540, 1000, 1.12);
const WTS = [35.4, PAGAR, PAGAR + 0.27, ANTES + 0.4, SAL - 0.2, SAL + 0.3];
const wal = (s: number) => ({
  x: 540,
  y: interpolate(s, WTS, [1560, 1040, 1040, 1630, 1630, 1060], {...clamp, easing: Easing.inOut(Easing.cubic)}),
  k: interpolate(s, WTS, [0.95, 0.95, 0.95, 0.6, 0.6, 0.95], {...clamp, easing: Easing.inOut(Easing.cubic)}),
});
const clasp = (w: {x: number; y: number; k: number}) => ({x: w.x + 152 * w.k, y: w.y + 8 * w.k});
const HOOK_OFF = {x: 52, y: -215};
const hookO = (s: number) => {
  if (s < PRISA) return {x: 540 + Math.sin(s * 2.1) * 10, y: 540 + Math.sin(s * 3) * 6};
  const c = clasp(wal(s));
  const tgt = {x: c.x + HOOK_OFF.x, y: c.y + HOOK_OFF.y};
  if (s < 35.4) { const p = eo(ro(s, PRISA, 35.4)); return {x: 540 + (tgt.x - 540) * p, y: 540 + (tgt.y - 540) * p}; }
  if (s < 36.3) return tgt;
  const c3 = clasp(wal(36.3));
  const p = eio(ro(s, 36.3, 36.95));
  return {x: c3.x + HOOK_OFF.x, y: c3.y + HOOK_OFF.y + (-520 - (c3.y + HOOK_OFF.y)) * p};
};
const CLASP_E8 = scr(E_END, clasp({x: 540, y: 1060, k: 0.95}).x, clasp({x: 540, y: 1060, k: 0.95}).y);

const TECLAS = [[10, 1240], [9, 1330], [7, 1420]].flatMap(([n, y], r) => Array.from({length: n}).map((_, i) => ({x: 540 + (i - (n - 1) / 2) * 88, y, r, i})));
const TXT1 = 'tienda-x';
const TXT2 = 'estafa';
const T1S = NOMBRE + 0.1, T1E = TIENDA + 0.45, T2S = PALABRA + 0.2, T2E = ESTAFA2 + 0.35;
const tipeo = (s: number) => {
  const n1 = Math.min(TXT1.length, Math.floor(ro(s, T1S, T1E) * (TXT1.length + 0.999)));
  const n2 = Math.min(TXT2.length, Math.floor(ro(s, T2S, T2E) * (TXT2.length + 0.999)));
  return {n1, n2};
};
// tiempo de cada letra (para el sonido y para la mano)
const LETRAS = [...TXT1.split('').map((_, i) => T1S + ((T1E - T1S) * (i + 1)) / (TXT1.length + 1)), ...TXT2.split('').map((_, i) => T2S + ((T2E - T2S) * (i + 1)) / (TXT2.length + 1))];

const SitioE: React.FC = () => {
  const {s, spr} = useS();
  const w = wal(s);
  const ho = hookO(s);
  // E6: etiqueta que se vuelve anzuelo
  const entra = spr(TRUCO - 0.25, 11, 110);
  const tagY = 540;
  const swing = s >= TRUCO - 0.2 ? 15 * Math.exp(-(s - TRUCO) * 1.3) * Math.sin((s - TRUCO) * 5.2) + 7 * pulso(s, PRECIO2) : 0;
  const tagS = (1 - eo(ro(s, BUENO, BUENO + 0.55))) * (0.92 + 0.12 * Math.max(0, golpe(s, PRECIO2, 16, 6)) + 0.08);
  const hookS = eo(ro(s, BUENO + 0.15, BUENO + 0.7));
  const hookVis = s > BUENO && s < 36.95;
  const tagVis = s >= TRUCO - 0.4 && tagS > 0.01;
  const tirando = s > 35.4 && s < 36.3;
  const sacud = s > 35.4 && s < PAGAR ? Math.sin(s * 70) * 5 : 0;
  const alerta = Math.max(0, golpe(s, RARO, 12, 3));
  // E7: busqueda
  const {n1, n2} = tipeo(s);
  const barra = spr(BUSCA, 12, 120);
  const cierre = eio(ro(s, SAL, SAL + 0.3));
  const winK = 1 - cierre;
  const idxLetra = LETRAS.filter((t) => t <= s).length - 1;
  const ult = idxLetra >= 0 ? LETRAS[idxLetra] : -9;
  const tecla = (i: number) => TECLAS[(i * 7 + 3) % TECLAS.length];
  const prev = idxLetra > 0 ? tecla(idxLetra - 1) : {x: 820, y: 1500};
  const cur = idxLetra >= 0 ? tecla(idxLetra) : {x: 820, y: 1500};
  const mv = eo(ro(s, ult - 0.08, ult));
  const hx = prev.x + (cur.x - prev.x) * mv;
  const hy = prev.y + (cur.y - prev.y) * mv + 16 * Math.max(0, golpe(s, ult, 24, 9)) * 0;
  const manoEn = ro(s, ANTES + 0.2, BUSCA + 0.3);
  const manoSal = ro(s, SAL, SAL + 0.3);
  const manoCierre = ro(s, SAL + 0.25, SAL + 0.5) * (1 - ro(s, AHI, AHI + 0.4));
  const px = hx + (540 - hx) * manoCierre;
  const py = hy + (840 - hy) * manoCierre;
  const carro = spr(COMPRAR, 10, 160) * (1 - ro(s, BUSCA - 0.05, BUSCA + 0.2));
  const filas = [{t: SI + 0.1, y: 930}, {t: ACEPTAN, y: 1030}, {t: TRANSF, y: 1130}];
  const dorada = s > AHI - 0.15;
  return (
    <AbsoluteFill>
      <Camara paradas={E_CAM}>
        <Textura tipo="papel" base="radial-gradient(circle at 50% 42%, #1b2a4a 0%, #0c1426 62%, #050810 100%)" linea="rgba(255,255,255,0.12)" luz="rgba(255,200,61,0.10)" semilla={9} />
        {s < PRISA && <Brillo x={540} y={680} r={520} color="rgba(255,200,61,0.3)" t0={PRECIO2} />}
        <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>
          {/* hilo */}
          {s < 36.95 && <line x1={540} y1={-120} x2={ho.x} y2={ho.y} stroke="#e2e8f0" strokeWidth={tirando ? 7 : 5} opacity={0.9} />}
          {/* etiqueta de precio */}
          {tagVis && (
            <g transform={`translate(${ho.x} ${ho.y - (1 - cl(entra)) * 900}) rotate(${swing}) scale(${tagS})`}>
              <path d="M -130 0 L 130 0 L 170 44 L 170 270 L -170 270 L -170 44 Z" fill="#fff" stroke="#c9b88a" strokeWidth={6} strokeLinejoin="round" />
              <path d="M -170 44 L -130 0 L 130 0 L 170 44 L 170 80 L -170 80 Z" fill="rgba(255,200,61,0.35)" />
              <circle cx={0} cy={30} r={14} fill="#0c1426" stroke="#c9b88a" strokeWidth={4} />
              <text x={0} y={200} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={104} fill={RED} stroke="#fff" strokeWidth={3}>-50 %</text>
            </g>
          )}
          {/* anzuelo */}
          {hookVis && (
            <g transform={`translate(${ho.x} ${ho.y}) rotate(${tirando ? sacud : 0}) scale(${hookS})`}>
              <circle cx={0} cy={0} r={16} fill="none" stroke="#e2e8f0" strokeWidth={8} />
              <path d="M 0 16 L 0 170 C 0 260 -105 262 -105 190" stroke="#cbd5e1" strokeWidth={20} fill="none" strokeLinecap="round" />
              <path d="M -105 190 L -86 212" stroke="#cbd5e1" strokeWidth={14} fill="none" strokeLinecap="round" />
              <path d="M 5 30 L 5 160" stroke="rgba(255,255,255,0.7)" strokeWidth={5} fill="none" strokeLinecap="round" />
            </g>
          )}
          {/* destello al transformarse */}
          {s > BUENO + 0.1 && s < BUENO + 0.6 && <g transform={`translate(${ho.x} ${ho.y + 80}) rotate(${(s - BUENO) * 200})`} opacity={1 - ro(s, BUENO + 0.3, BUENO + 0.6)}><polygon points={starPts(90)} fill="#fff" /></g>}
          {/* billetes que salen al pagar */}
          {s > PAGAR && s < PAGAR + 1.3 && [0, 1, 2, 3, 4, 5, 6].map((i) => {
            const t = s - PAGAR;
            const a = -Math.PI / 2 + (i - 3) * 0.5;
            return <Bill key={i} x={540 + Math.cos(a) * (360 + 40 * i) * t} y={1040 + Math.sin(a) * (360 + 40 * i) * t + 800 * t * t} r={t * 220 * (i % 2 ? 1 : -1)} k={0.5} op={1 - ro(t, 0.8, 1.3)} />;
          })}
          {/* cartera de cuero */}
          <Cartera x={w.x + sacud} y={w.y} k={w.k} bills={s < PAGAR ? 1 : s < SAL - 0.2 ? 0.25 : 0} oro={dorada} />
          {/* carrito de la compra */}
          {carro > 0.01 && (
            <g transform={`translate(540 860) scale(${1.4 * carro})`}>
              <circle r={90} fill="rgba(255,255,255,0.08)" stroke="#fff" strokeWidth={5} />
              <path d="M -50 -32 L -32 -32 L -14 24 L 34 24 L 46 -16 L -26 -16" stroke="#fff" strokeWidth={9} fill="none" strokeLinecap="round" strokeLinejoin="round" />
              <circle cx={-6} cy={46} r={9} fill="#fff" /><circle cx={30} cy={46} r={9} fill="#fff" />
            </g>
          )}
          {/* ventana de busqueda */}
          {s > BUSCA - 0.1 && winK > 0.01 && (
            <g transform={`translate(540 900) scale(${winK}) translate(-540 -900) translate(0 ${(1 - cl(barra)) * -500})`}>
              <rect x={100} y={706} width={900} height={140} rx={70} fill="rgba(0,0,0,0.4)" transform="translate(8 12)" />
              <rect x={90} y={694} width={900} height={140} rx={70} fill="#f4f6fb" stroke="#9fb0d0" strokeWidth={6} />
              <circle cx={170} cy={758} r={26} fill="none" stroke="#6b7488" strokeWidth={9} />
              <line x1={190} y1={778} x2={212} y2={802} stroke="#6b7488" strokeWidth={9} strokeLinecap="round" />
              <text x={250} y={786} fontFamily={FONT} fontWeight={600} fontSize={64} fill="#1f2937">
                {TXT1.slice(0, n1)}
                {n2 > 0 && <tspan fill={RED} fontWeight={800}>{' ' + TXT2.slice(0, n2)}</tspan>}
                {n1 + n2 < TXT1.length + TXT2.length && Math.floor(s * 3) % 2 === 0 ? '|' : ''}
              </text>
              {n2 > 0 && <line x1={250 + 31 * TXT1.length + 20} y1={806} x2={250 + 31 * TXT1.length + 20 + 31 * n2} y2={806} stroke={RED} strokeWidth={5} />}
              {filas.map((f, i) => {
                const k = spr(f.t, 12, 130);
                const blink = 1 + 0.2 * alerta * (i + 1) / 3;
                return k > 0.01 ? (
                  <g key={i} opacity={cl(k)} transform={`translate(${(1 - cl(k)) * 400} 0)`}>
                    <rect x={110} y={f.y - 40} width={860} height={80} rx={18} fill="#1e2433" stroke={RED} strokeWidth={4} />
                    <g transform="translate(0 0)"><Alerta x={170} y={f.y - 2} k={0.9 * blink} /></g>
                    <rect x={230} y={f.y - 20} width={i === 0 ? 380 : i === 1 ? 300 : 420} height={14} rx={7} fill="#56607a" />
                    <rect x={230} y={f.y + 6} width={220} height={12} rx={6} fill="#3b4358" />
                    <rect x={810} y={f.y - 22} width={130} height={44} rx={14} fill={RED} />
                    {i === 2 && <g transform={`translate(660 ${f.y})`}><path d="M -50 -8 L 50 -8 M 30 -24 L 50 -8 L 30 8 M 50 12 L -50 12 M -30 -4 L -50 12 L -30 28" stroke="#cfd6e4" strokeWidth={6} fill="none" strokeLinecap="round" strokeLinejoin="round" /></g>}
                  </g>
                ) : null;
              })}
              {TECLAS.map((q, i) => {
                const k = spr(BUSCA + 0.05 * (i % 10), 12, 130);
                const pres = idxLetra >= 0 && tecla(idxLetra).x === q.x && tecla(idxLetra).y === q.y && s - ult < 0.12;
                return <rect key={i} x={q.x - 38} y={q.y - 30 + (pres ? 5 : 0)} width={76} height={62} rx={12} fill={pres ? GOLD : '#3a4358'} stroke="#1a2030" strokeWidth={4} opacity={cl(k)} />;
              })}
            </g>
          )}
          {/* la mano (piel trigueña) */}
          {manoEn > 0 && manoSal < 1 && s < AHI + 0.4 && (
            <Mano x={px + 20 * 0.62 + 360 * (1 - manoEn) + 500 * manoSal * (1 - manoCierre)} y={py + 220 * 0.62 + 500 * (1 - manoEn) + 12 * Math.max(0, golpe(s, ult, 24, 9))} r={0} k={0.62} />
          )}
        </svg>
        {s > BUENO && s < 36 && <Brillo x={ho.x} y={ho.y + 140} r={260} color="rgba(255,200,61,0.3)" />}
        <Ondas x={540} y={680} t0={PRECIO2} color={GOLD} radio={420} />
        <Ondas x={clasp(wal(35.4)).x} y={clasp(wal(35.4)).y} t0={35.4} color="rgba(255,255,255,0.9)" radio={260} />
        <Ondas x={540} y={1040} t0={PAGAR} color={RED} radio={520} />
        <Ondas x={540} y={1060} t0={AHI - 0.15} color={GOLD} radio={520} />
        {dorada && <Brillo x={540} y={1060} r={460} color="rgba(255,200,61,0.5)" t0={AHI - 0.15} />}
      </Camara>
      <Destello t0={PAGAR} fuerza={0.35} />
      {s > RARO - 0.1 && s < RARO + 1.2 && <AbsoluteFill style={{background: `radial-gradient(circle, transparent 45%, rgba(255,77,77,${0.38 * alerta}) 100%)`}} />}
      <Polvo n={16} color="rgba(255,230,180,0.35)" />
    </AbsoluteFill>
  );
};

