  const p2 = <Paso t={EN} tipo="barrido" antes={p1} despues={<SitioC />} />;
  const p3 = <Paso t={EL} tipo="alejar" x={540} y={1000} antes={p2} despues={<SitioE />} />;
  const p4 = <Paso t={DALE} tipo="forma" dur={0.45} x={CLASP_E8.x} y={CLASP_E8.y} antes={p3} despues={<SitioA fase="fin" />} />;
  return (
    <AbsoluteFill style={{background: '#000'}}>
      {p4}
      <AbsoluteFill style={{background: tint, mixBlendMode: 'soft-light'}} />
      <Profundidad manchas={3} semilla={4} color="rgba(8,10,30,0.5)" />
    </AbsoluteFill>
  );
};

